use Illuminate\Support\Facades\Http;

function recognizeShortVoice(string $ogg, string $apiKey): string
{
    $response = Http::withHeaders(['Authorization' => 'Api-Key '.$apiKey])
        ->connectTimeout(5)
        ->timeout(25)
        ->withBody($ogg, 'application/octet-stream')
        ->post('https://stt.api.cloud.yandex.net/speech/v1/stt:recognize?lang=ru-RU&format=oggopus');

    $text = $response->json('result');
    if (!$response->successful() || !is_string($text)) {
        throw new RuntimeException('SpeechKit не вернул текст.');
    }

    return trim($text);
}
